export const PETS=groups.flatMap((group,gi)=>group.friends.map(([name,species,trait,story],cell)=>({
  id:gi*25+cell+1,name,species,trait,story,world:group.world,sheet:group.sheet,cell,
  rarity:gi===3?'Mythic':gi===2?'Rare':gi===1?'Uncommon':'Common'
})));
if(PETS.length!==100||new Set(PETS.map(p=>p.name)).size!==100)throw new Error('Pet atlas must contain 100 unique names');
